def logistic_map(width: int, height: int, x_coords: list[int], y_coords: list[int]) -> list[list[int | None]]:
    if not x_coords or not y_coords:
        return [[None for _ in range(width)] for _ in range(height)]

    supply_points = list(zip(x_coords, y_coords))
    result = []

    for y in range(height):
        row = []
        for x in range(width):
            min_dist = float('inf')
            for sx, sy in supply_points:
                dist = abs(x - sx) + abs(y - sy)
                if dist < min_dist:
                    min_dist = dist
            row.append(min_dist)
        result.append(row)

    return result
